import type { OrgId } from "@/types/common";
import type { Subscription, WorkspaceLockReason } from "@/types/billing";

/**
 * The read-only lock on a workspace whose subscription is not in good
 * standing. `lockReasonFor()` is the one place the rule is written down;
 * `BillingService.assertWorkspaceWritable()` applies it on the write paths and
 * the billing summary reports it, so the two cannot disagree.
 */

/** Thrown by a write refused because its workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only (${reason.replace("_", " ")}). Update billing to make changes.`);
    this.name = "WorkspaceLockedError";
  }
}

/** True once `stamp` has been reached, i.e. `now` is at or after it. */
function reached(stamp: string, now: Date): boolean {
  return now.getTime() >= new Date(stamp).getTime();
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable.
 *
 * A workspace with no subscription row, or an `active` one, is writable. A
 * trial locks once its period end is reached; a cancellation locks once its
 * `cancelAt` is reached (none at all means it took effect already), so one
 * scheduled for later keeps the workspace writable until then.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null || reached(subscription.cancelAt, now)
        ? "canceled"
        : null;
  }
}
EOF

