/**
 * A workspace whose subscription is not in good standing is read-only: member
 * writes are refused before anything is stored or published, while reads,
 * billing, a member's own notification housekeeping and Taskflow's background
 * work keep going.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { eq } from "drizzle-orm";
import { WorkspaceLockedError } from "@/lib/billing-lock";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { getDb } from "@/server/db";
import { subscriptions } from "@/server/db/schema/billing";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as billingService from "@/server/services/billing-service";
import * as commentService from "@/server/services/comment-service";
import * as featureFlagService from "@/server/services/feature-flag-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as labelService from "@/server/services/label-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SubscriptionStatus } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Comment } from "@/types/comment";

let cleanup: () => void;
let tenant: Tenant;
let issue: Issue;
let comment: Comment;

const HOUR = 3_600_000;

function setSubscription(
  status: SubscriptionStatus,
  extra: { cancelAt?: IsoTimestamp | null; currentPeriodEnd?: IsoTimestamp } = {},
): void {
  getDb()
    .update(subscriptions)
    .set({ status, ...extra })
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
}

function at(offsetMs: number): IsoTimestamp {
  return new Date(Date.now() + offsetMs).toISOString() as IsoTimestamp;
}

/** Runs `write` and asserts it is refused by the lock, with nothing published. */
async function expectLocked(write: () => Promise<unknown>): Promise<void> {
  const seen: string[] = [];
  const off = [
    subscribe("issue.created", () => void seen.push("issue.created")),
    subscribe("issue.updated", () => void seen.push("issue.updated")),
    subscribe("comment.created", () => void seen.push("comment.created")),
    subscribe("project.created", () => void seen.push("project.created")),
    subscribe("member.role_changed", () => void seen.push("member.role_changed")),
    subscribe("member.removed", () => void seen.push("member.removed")),
    subscribe("member.invited", () => void seen.push("member.invited")),
  ];
  try {
    await expect(write()).rejects.toBeInstanceOf(WorkspaceLockedError);
  } finally {
    for (const unsubscribe of off) unsubscribe();
  }
  expect(seen).toEqual([]);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("locked", "growth");
  const { owner } = tenant.actors;

  issue = await issueService.createIssue(
    owner,
    issueInput(tenant.org.id, tenant.project.id),
  );
  comment = await commentService.createComment(owner, {
    orgId: tenant.org.id,
    issueId: issue.id,
    body: "before the lock",
    parentId: null,
    mentionedUserIds: [],
  });
});

beforeEach(() => {
  setSubscription("past_due");
});

afterAll(() => {
  cleanup();
});

describe("assertWorkspaceWritable", () => {
  it("names the reason the workspace is locked", async () => {
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).rejects.toMatchObject({ orgId: tenant.org.id, reason: "past_due" });
  });

  it("lets an active workspace through", async () => {
    setSubscription("active");
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();
  });

  it("evaluates a trial and a cancellation at the given time", async () => {
    const period = new Date(Date.now() + 24 * HOUR);
    setSubscription("trialing", {
      currentPeriodEnd: period.toISOString() as IsoTimestamp,
    });
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, period),
    ).rejects.toMatchObject({ reason: "trial_ended" });

    setSubscription("canceled", { cancelAt: at(24 * HOUR) });
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(
        tenant.org.id,
