    await expectLocked(() =>
      commentService.deleteComment(owner, { orgId, commentId: comment.id }),
    );

    await expectLocked(() =>
      projectService.createProject(owner, {
        orgId,
        name: "Another",
        key: "ANO",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      }),
    );
    await expectLocked(() =>
      projectService.updateProject(owner, {
        orgId,
        projectId: tenant.project.id,
        name: "Renamed",
      }),
    );
    await expectLocked(() =>
      projectService.archiveProject(owner, {
        orgId,
        projectId: tenant.project.id,
        archiveIssues: true,
      }),
    );
    await expectLocked(() =>
      projectService.restoreProject(owner, orgId, tenant.project.id),
    );

    await expectLocked(() =>
      labelService.createLabel(owner, { orgId, name: "bug", color: "#ff0000" }),
    );
    await expectLocked(() =>
      labelService.updateLabel(owner, {
        orgId,
        labelId: "01HZZZLABELLABELLABELLABEL" as never,
        name: "renamed",
      }),
    );
    await expectLocked(() =>
      labelService.deleteLabel(owner, orgId, "01HZZZLABELLABELLABELLABEL" as never),
    );

    await expectLocked(() =>
      attachmentService.addAttachment(owner, {
        orgId,
        issueId: issue.id,
        filename: "spec.pdf",
        contentType: "application/pdf",
        sizeBytes: 1024,
        storageKey: "spec.pdf",
      } as never),
    );
    await expectLocked(() =>
      attachmentService.removeAttachment(owner, {
        orgId,
        attachmentId: "01HZZZATTACHATTACHATTACHAT" as never,
      }),
    );

    const live = await projectService.getProject(owner, orgId, tenant.project.slug);
    expect(live.project.archivedAt).toBeNull();
