  it("refuses membership, workspace-settings, flag and webhook writes", async () => {
    const { owner } = tenant.actors;
    const orgId = tenant.org.id;
    const member = await memberRepo.findMember(orgId, tenant.userIds.member);
    expect(member).not.toBeNull();

