/** The workspace lock rule and how its error is reported. */
import { describe, expect, it } from "vitest";
import { WorkspaceLockedError, lockReasonFor } from "@/lib/billing-lock";
import { isDomainError, toAppError } from "@/lib/errors";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp, SubscriptionId } from "@/types/common";
import { ORG_A } from "../helpers/factories";

const NOW = new Date("2026-06-15T12:00:00.000Z");

function stamp(offsetMs: number): IsoTimestamp {
  return new Date(NOW.getTime() + offsetMs).toISOString() as IsoTimestamp;
}

function makeSubscription(overrides: Partial<Subscription> = {}): Subscription {
  return {
    id: "01HZZZSUBSUBSUBSUBSUBSUBSU" as SubscriptionId,
    orgId: ORG_A,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 5,
    currentPeriodStart: stamp(-14 * 86_400_000),
    currentPeriodEnd: stamp(14 * 86_400_000),
    cancelAt: null,
    createdAt: stamp(-14 * 86_400_000),
    updatedAt: stamp(-14 * 86_400_000),
    ...overrides,
  };
}

describe("lib/billing-lock lockReasonFor", () => {
  it("leaves a workspace without a subscription writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
  });

  it("leaves an active subscription writable", () => {
    expect(lockReasonFor(makeSubscription(), NOW)).toBeNull();
  });

  it("locks a past-due subscription", () => {
    expect(lockReasonFor(makeSubscription({ status: "past_due" }), NOW)).toBe(
      "past_due",
    );
  });

  it("locks a trial from the moment its period end is reached", () => {
    const trial = (offset: number) =>
      makeSubscription({ status: "trialing", currentPeriodEnd: stamp(offset) });

    expect(lockReasonFor(trial(1), NOW)).toBeNull();
    expect(lockReasonFor(trial(0), NOW)).toBe("trial_ended");
    expect(lockReasonFor(trial(-1), NOW)).toBe("trial_ended");
  });

  it("locks a cancellation from the moment its date is reached", () => {
    const canceled = (cancelAt: IsoTimestamp | null) =>
      makeSubscription({ status: "canceled", cancelAt });

    expect(lockReasonFor(canceled(stamp(1)), NOW)).toBeNull();
    expect(lockReasonFor(canceled(stamp(0)), NOW)).toBe("canceled");
    expect(lockReasonFor(canceled(stamp(-1)), NOW)).toBe("canceled");
  });

  it("counts a cancellation with no date as canceled now", () => {
    expect(lockReasonFor(makeSubscription({ status: "canceled" }), NOW)).toBe(
      "canceled",
    );
  });

  it("evaluates at the current time when none is given", () => {
    const ended = makeSubscription({
      status: "trialing",
      currentPeriodEnd: new Date(Date.now() - 1_000).toISOString() as IsoTimestamp,
    });
    expect(lockReasonFor(ended)).toBe("trial_ended");
  });
});

describe("lib/billing-lock WorkspaceLockedError", () => {
  it("carries the org and the reason under the plan-limit code", () => {
    const error = new WorkspaceLockedError(ORG_A, "past_due");
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(error.reason).toBe("past_due");
  });

  it("is reported as `plan_limit_exceeded` with the reason in meta", () => {
    const error = new WorkspaceLockedError(ORG_A, "trial_ended");
    const shape = toAppError(error);
    expect(shape.code).toBe("plan_limit_exceeded");
    expect(shape.meta?.reason).toBe("trial_ended");
    expect(isDomainError(error)).toBe(true);
  });
});
