    const orgId = tenant.org.id;
    const member = tenant.actors.member;

    await expect(notificationService.markAllRead(member, orgId)).resolves.toBeTypeOf(
      "number",
    );
    await expect(
      notificationService.updatePreference(member, {
        orgId,
        userId: member.userId,
        kind: "comment_created",
        inApp: true,
        email: false,
        digestOnly: false,
      }),
    ).resolves.toMatchObject({ email: false });
  });

  it("still lets the owner manage billing, and a plan change unlocks", async () => {
    const { owner } = tenant.actors;
    const orgId = tenant.org.id;

    await expect(
      billingService.updateSeats(owner, { orgId, seats: 3 }),
    ).resolves.toMatchObject({ seats: 3 });
    await expect(
      billingService.cancelSubscription(owner, { orgId, cancelImmediately: true }),
    ).resolves.toMatchObject({ status: "canceled" });
    await expect(
      billingService.assertWorkspaceWritable(orgId),
    ).rejects.toMatchObject({ reason: "canceled" });

    await billingService.changePlan(owner, {
      orgId,
      plan: "growth",
      interval: "monthly",
    });
    await expect(
      billingService.assertWorkspaceWritable(orgId),
    ).resolves.toBeUndefined();
    await expect(
      issueService.createIssue(owner, issueInput(orgId, tenant.project.id)),
    ).resolves.toBeDefined();
  });

  it("still delivers notifications from the fan-out", async () => {
    const orgId = tenant.org.id;
    await expect(
      notificationService.notify(orgId, "issue_assigned", [tenant.userIds.member], {
        title: "hello",
        body: "from the fan-out",
        href: "/x",
        actorId: null,
      }),
    ).resolves.toHaveLength(1);
  });

  it("moves an ended trial to free, which unlocks it", async () => {
    const orgId = tenant.org.id;
    const free = await createTenant("locked-trial", "free");

    getDb()
      .update(subscriptions)
      .set({
        plan: "starter",
        status: "trialing",
        currentPeriodEnd: at(-HOUR),
      })
      .where(eq(subscriptions.orgId, free.org.id))
      .run();

    await expect(
      billingService.assertWorkspaceWritable(free.org.id),
    ).rejects.toMatchObject({ reason: "trial_ended" });

    await runTrialExpiryJob(new Date());

    await expect(
      subscriptionRepo.findSubscription(free.org.id),
    ).resolves.toMatchObject({ plan: "free", status: "active" });
    await expect(
      billingService.assertWorkspaceWritable(free.org.id),
    ).resolves.toBeUndefined();
    expect(orgId).not.toBe(free.org.id);
  });

  it("lets the owner delete the workspace", async () => {
    const doomed = await createTenant("locked-delete", "growth");
    setSubscriptionFor(doomed, "past_due");

    await expect(
      organizationService.deleteOrganization(doomed.actors.owner, {
        orgId: doomed.org.id,
        confirmSlug: doomed.org.slug,
      }),
    ).resolves.toMatchObject({ id: doomed.org.id });
  });
});

function setSubscriptionFor(target: Tenant, status: SubscriptionStatus): void {
  getDb()
    .update(subscriptions)
    .set({ status })
    .where(eq(subscriptions.orgId, target.org.id))
    .run();
}
